import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import confetti from 'canvas-confetti';
import { useAuth } from '../context/AuthContext';
import KibaShield from '../components/KibaShield';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const EyeOpen = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M12 5C7 5 2.73 8.11 1 12.5C2.73 16.89 7 20 12 20C17 20 21.27 16.89 23 12.5C21.27 8.11 17 5 12 5Z" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="12.5" r="3.5" stroke="#0EA5E9" strokeWidth="2"/>
    <circle cx="12" cy="12.5" r="1.5" fill="#0EA5E9"/>
  </svg>
);

const EyeClosed = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M2 2L22 22" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round"/>
    <path d="M6.71 6.71C4.56 8.08 2.9 10.11 2 12.5C3.73 16.89 8 20 13 20C15.11 20 17.07 19.32 18.66 18.18" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.88 4.13C10.57 4.05 11.28 4 12 4C17 4 21.27 7.11 23 11.5C22.47 12.87 21.69 14.09 20.72 15.12" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.76 9.76C9.29 10.23 9 10.88 9 11.6C9 13.14 10.35 14.4 12 14.4C12.76 14.4 13.45 14.12 13.96 13.66" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const demoAccounts = [
  {
    label: 'Administrator',
    color: '#EF4444',
    bg: '#FEE2E2',
    identifier: 'admin@kibalitest.com',
    password: 'Admin1234'
  },
  {
    label: 'HR Staff',
    color: '#F59E0B',
    bg: '#FEF3C7',
    identifier: 'staff@kibalitest.com',
    password: 'Staff1234'
  },
  {
    label: 'Job Applicant',
    color: '#0EA5E9',
    bg: '#E0F2FE',
    identifier: '0712345678',
    password: 'Customer1234'
  }
];

const Login = () => {
  const { login, darkMode } = useAuth();
  const navigate = useNavigate();
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');
  const [showDemo, setShowDemo] = useState(false);

  useEffect(() => {
    const remembered = localStorage.getItem('kibaliRememberMe');
    if (remembered) {
      setIdentifier(remembered);
      setRememberMe(true);
      setPose(8);
    }
  }, []);

  const handleDemoSelect = (account) => {
    setIdentifier(account.identifier);
    setPassword(account.password);
    setShowDemo(false);
    setPose(8);
    setShieldState('idle');
  };

  const handleIdentifierChange = (e) => {
    setIdentifier(e.target.value);
    if (e.target.value.length > 0) setPose(8);
    else setPose(1);
  };

  const handlePasswordFocus = () => {
    setPose(9);
    setShieldState('idle');
  };

  const handlePasswordBlur = () => {
    if (identifier.length > 0) setPose(8);
    else setPose(1);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!identifier || !password) {
      setError('Please fill in all fields');
      setPose(3);
      setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    setLoading(true);
    setPose(7);
    setShieldState('idle');
    try {
      const res = await axios.post(`${API}/api/auth/login`, { identifier, password });
      setPose(2);
      setShieldState('success');
      confetti({
        particleCount: 120,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#10B981', '#0EA5E9', '#1E3A5F']
      });
      if (rememberMe) {
        localStorage.setItem('kibaliRememberMe', identifier);
      } else {
        localStorage.removeItem('kibaliRememberMe');
      }
      setTimeout(() => {
        login(res.data.user, res.data.token);
        const role = res.data.user.role;
        navigate(role === 'admin' ? '/admin' : role === 'staff' ? '/staff' : '/dashboard');
      }, 1500);
    } catch (err) {
      const msg = err.response?.data?.message || 'Something went wrong. Please try again.';
      setError(msg);
      setPose(4);
      setShieldState('danger');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally {
      setLoading(false);
    }
  };

  const inputStyle = {
    width: '100%',
    padding: '14px 48px 14px 16px',
    border: '2px solid #E2E8F0',
    borderRadius: '12px',
    fontSize: '15px',
    fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#fff',
    color: darkMode ? '#F1F5F9' : '#1E293B',
    outline: 'none',
    boxSizing: 'border-box'
  };

  const normalInputStyle = {
    width: '100%',
    padding: '14px 16px',
    border: '2px solid #E2E8F0',
    borderRadius: '12px',
    fontSize: '15px',
    fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#fff',
    color: darkMode ? '#F1F5F9' : '#1E293B',
    outline: 'none',
    boxSizing: 'border-box'
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F8FAFC' }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px 16px' }}>
        <div style={{ display: 'flex', gap: '56px', alignItems: 'center', width: '100%', maxWidth: '920px', flexWrap: 'wrap', justifyContent: 'center' }}>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '20px' }}>
            <KibaShield pose={pose} shieldState={shieldState} customLabel={loading ? 'Processing securely...' : null} />
            <div style={{ textAlign: 'center' }}>
              <h1 style={{ fontSize: '30px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', margin: 0 }}>KibaliGuard</h1>
              <p style={{ color: '#64748B', fontSize: '14px', marginTop: '6px' }}>Your data. Your rules. Your control.</p>
            </div>
          </div>

          <div style={{
            background: darkMode ? '#1E293B' : '#ffffff',
            borderRadius: '24px',
            padding: '44px 40px',
            boxShadow: '0 8px 48px rgba(30,58,95,0.13)',
            width: '100%',
            maxWidth: '420px'
          }}>
            <h2 style={{ fontSize: '26px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '6px' }}>
              Welcome back
            </h2>
            <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '32px' }}>
              Sign in to your KibaliGuard account
            </p>

            {error && (
              <div style={{ background: '#FEF2F2', color: '#EF4444', border: '1px solid #FECACA', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', fontWeight: 500, marginBottom: '20px' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Email or phone number
                </label>
                <input
                  type="text"
                  placeholder="e.g. your@gmail.com or 07XXXXXXXX"
                  value={identifier}
                  onChange={handleIdentifierChange}
                  style={normalInputStyle}
                />
              </div>

              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Password
                </label>
                <div style={{ position: 'relative' }}>
                  <input
                    type={showPassword ? 'text' : 'password'}
                    placeholder="Enter your password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    onFocus={handlePasswordFocus}
                    onBlur={handlePasswordBlur}
                    style={inputStyle}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(prev => !prev)}
                    style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', padding: '4px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                  >
                    {showPassword ? <EyeOpen /> : <EyeClosed />}
                  </button>
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '8px' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                    style={{ width: '16px', height: '16px', accentColor: '#1E3A5F', cursor: 'pointer' }}
                  />
                  <span style={{ fontSize: '14px', color: darkMode ? '#CBD5E1' : '#64748B', fontWeight: 500 }}>
                    Remember me
                  </span>
                </label>
                <Link to="/forgot-password" style={{ color: '#0EA5E9', fontSize: '14px', textDecoration: 'none', fontWeight: 600 }}>
                  Forgot password?
                </Link>
              </div>

              <button
                type="submit"
                disabled={loading}
                style={{
                  width: '100%',
                  padding: '15px',
                  background: loading ? '#0EA5E9' : '#1E3A5F',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '12px',
                  fontWeight: 700,
                  fontSize: '16px',
                  cursor: loading ? 'not-allowed' : 'pointer',
                  fontFamily: 'Inter, sans-serif',
                  marginBottom: '20px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '10px'
                }}
              >
                {loading ? (
                  <>
                    <span style={{ width: '18px', height: '18px', border: '3px solid rgba(255,255,255,0.3)', borderTop: '3px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                    Signing you in...
                  </>
                ) : 'Sign In'}
              </button>
            </form>

            {/* DEMO ACCOUNTS SECTION */}
            <div style={{ borderTop: `1px solid ${darkMode ? '#334155' : '#E2E8F0'}`, paddingTop: '16px', marginBottom: '16px' }}>
              <div style={{ position: 'relative' }}>
                <button
                  type="button"
                  onClick={() => setShowDemo(!showDemo)}
                  style={{
                    width: '100%',
                    padding: '10px 16px',
                    background: darkMode ? '#0F172A' : '#F8FAFC',
                    border: `1.5px solid ${darkMode ? '#334155' : '#E2E8F0'}`,
                    borderRadius: '10px',
                    fontWeight: 600,
                    fontSize: '13px',
                    color: '#64748B',
                    cursor: 'pointer',
                    fontFamily: 'Inter, sans-serif',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between'
                  }}
                >
                  <span>Try a demo account</span>
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" style={{ transform: showDemo ? 'rotate(180deg)' : 'rotate(0deg)', transition: 'transform 0.2s' }}>
                    <polyline points="6 9 12 15 18 9" stroke="#64748B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </button>

                {showDemo && (
                  <div style={{
                    position: 'absolute',
                    bottom: '100%',
                    left: 0,
                    right: 0,
                    background: darkMode ? '#1E293B' : '#fff',
                    border: `1.5px solid ${darkMode ? '#334155' : '#E2E8F0'}`,
                    borderRadius: '12px',
                    padding: '8px',
                    marginBottom: '6px',
                    boxShadow: '0 8px 24px rgba(0,0,0,0.12)',
                    zIndex: 10
                  }}>
                    <p style={{ fontSize: '11px', color: '#94A3B8', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.5px', padding: '4px 8px 8px', margin: 0 }}>
                      Select account type to auto-fill
                    </p>
                    {demoAccounts.map(account => (
                      <button
                        key={account.label}
                        type="button"
                        onClick={() => handleDemoSelect(account)}
                        style={{
                          width: '100%',
                          padding: '10px 12px',
                          background: 'transparent',
                          border: 'none',
                          borderRadius: '8px',
                          cursor: 'pointer',
                          fontFamily: 'Inter, sans-serif',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '10px',
                          textAlign: 'left',
                          transition: 'background 0.15s'
                        }}
                        onMouseEnter={e => e.currentTarget.style.background = darkMode ? '#0F172A' : '#F8FAFC'}
                        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                      >
                        <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: account.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                          <span style={{ fontSize: '14px', fontWeight: 800, color: account.color }}>
                            {account.label.charAt(0)}
                          </span>
                        </div>
                        <div>
                          <p style={{ fontWeight: 700, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B', margin: 0 }}>{account.label}</p>
                          <p style={{ fontSize: '11px', color: '#94A3B8', margin: '1px 0 0', fontFamily: 'Roboto Mono, monospace' }}>{account.identifier}</p>
                        </div>
                        <div style={{ marginLeft: 'auto' }}>
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                            <polyline points="9 18 15 12 9 6" stroke="#94A3B8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                          </svg>
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>

            <div style={{ textAlign: 'center', fontSize: '14px', color: '#64748B' }}>
              Do not have an account?{' '}
              <Link to="/register" style={{ color: '#0EA5E9', fontWeight: 700, textDecoration: 'none' }}>
                Register here
              </Link>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Login;
